  'help.close': 'Închide',
  'help.ticketError': 'Eroare la trimiterea ticket-ului. Încearcă din nou.',
  'help.type.cant_login': 'Nu pot să mă conectez',
  'help.type.email_issue': 'Problemă cu email-ul',
  'help.type.security': 'Securitate',
  'help.type.other': 'Altceva',
  'help.faq.cantLogin.q': 'Nu pot accesa contul meu',
  'help.faq.cantLogin.a': 'Verifică dacă folosești email-ul și parola corecte. Dacă ai uitat parola, apasă pe "Ai uitat parola?" pe ecranul de conectare. Dacă problema persistă, creează un ticket de suport.',
  'help.faq.notReceiving.q': 'Nu primesc email-uri',
  'help.faq.notReceiving.a': 'Verifică mai întâi folderul Spam. Asigură-te că stocarea ta nu este plină. Dacă problema continuă, confirmă că expeditorul are adresa corectă și creează un ticket.',
  'help.faq.cantSend.q': 'Nu pot trimite email-uri',
  'help.faq.cantSend.a': 'Verifică conexiunea ta la internet și dacă adresa destinatarului este corectă. Asigură-te că atașamentele nu depășesc 25MB. Încearcă din nou în câteva minute.',
  'help.faq.forgotPassword.q': 'Am uitat parola mea',
  'help.faq.forgotPassword.a': 'Pe ecranul de conectare, apasă pe "Ai uitat parola?" și urmează instrucțiunile pentru a-ți reseta parola prin email-ul de recuperare.',
  'help.faq.accountSecurity.q': 'Cred că contul meu a fost compromis',
  'help.faq.accountSecurity.a': 'Schimbă-ți imediat parola. Verifică folderul Trimise pentru mesaje pe care nu le-ai trimis. Activează autentificarea în doi pași în Setări > Securitate. Dacă este necesar, creează un ticket urgent.',
  'help.faq.appAccess.q': 'Cum accesez aplicația pe telefon?',
  'help.faq.appAccess.a': 'Poți accesa Chatyy prin browser pe chatyy.com.br, sau poți descărca aplicația noastră din magazinul de aplicații al dispozitivului tău.',
  'privacy.title': 'Politica de Confidențialitate',
  'privacy.subtitle': 'Cum protejăm și gestionăm datele tale',
  'privacy.lastUpdated': 'Ultima actualizare: Martie 2026',
  'privacy.dataCollection.title': 'Colectarea Datelor',
  'privacy.dataCollection.body': 'Colectăm doar informațiile necesare pentru serviciul de email: numele tău, adresa de email și conținutul mesajelor trimise și primite. Nu vindem și nu împărtășim datele tale personale cu terți în scopuri de marketing.',
  'privacy.dataUsage.title': 'Cum Folosim Datele Tale',
  'privacy.dataUsage.body': 'Datele tale sunt folosite exclusiv pentru a opera și îmbunătăți serviciul de email, inclusiv livrarea mesajelor, filtrarea spam-ului, funcții de IA (cu consimțământul tău) și securitatea contului.',
  'privacy.dataSecurity.title': 'Securitatea Datelor',
  'privacy.dataSecurity.body': 'Folosim criptare standard din industrie (TLS/SSL) pentru toate datele în tranzit și în repaus. Sesiunile sunt protejate cu token-uri criptate și protecție CSRF. Audităm regulat practicile noastre de securitate.',
  'privacy.cookies.title': 'Cookies și Stocare Locală',
  'privacy.cookies.body': 'Folosim cookies esențiale și stocare locală pentru a menține sesiunea ta, a-ți aminti preferințele (temă, limbă) și a oferi o experiență fluidă. Nu folosim cookies de urmărire de la terți.',
  'privacy.thirdParties.title': 'Servicii de Terti',
  'privacy.thirdParties.body': 'Putem folosi servicii de la terți pentru funcționalități specifice, cum ar fi IA (Anthropic Claude) și notificări push. Aceste servicii urmează propriile lor politici de confidențialitate și procesează doar minimul de date necesar.',
  'privacy.rights.title': 'Drepturile Tale',
  'privacy.rights.body': 'Ai dreptul de a accesa, corecta, exporta sau șterge datele tale personale în orice moment. Poți gestiona datele tale în Setări sau contactând suportul nostru.',
  'privacy.contact.title': 'Contactează-ne',
  'privacy.contact.body': 'Pentru întrebări legate de confidențialitate sau solicitări de date, contactează-ne la privacy@chatyy.com.br. Vom răspunde în maxim 30 de zile.',
  'terms.title': 'Termeni de Serviciu',
  'terms.subtitle': 'Ghiduri de utilizare a Chatyy',
  'terms.lastUpdated': 'Ultima actualizare: Martie 2026',
  'terms.acceptance.title': 'Acceptarea Termenilor',
  'terms.acceptance.body': 'Prin accesarea sau utilizarea Chatyy, ești de acord cu acești Termeni de Serviciu. Dacă nu ești de acord cu vreo parte din acești termeni, nu folosi serviciul.',
  'terms.services.title': 'Descrierea Serviciilor',
  'terms.services.body': 'Chatyy oferă servicii de comunicare prin email, inclusiv trimiterea, primirea și gestionarea email-urilor, precum și funcții de IA, integrare cu calendarul și videoconferință.',
  'terms.accounts.title': 'Conturi de Utilizator',
  'terms.accounts.body': 'Ești responsabil pentru menținerea securității acreditivelor tale. Nu împărtăși parola ta și nu permite accesul neautorizat la contul tău. Trebuie să ai cel puțin 13 ani pentru a folosi acest serviciu.',
  'terms.conduct.title': 'Utilizare Acceptabilă',
  'terms.conduct.body': 'Ești de acord să nu folosești serviciul pentru a trimite spam, malware, phishing sau orice conținut ilegal. Nu încerca să accesezi conturile altor utilizatori sau să întrerupi infrastructura serviciului.',
  'terms.content.title': 'Proprietatea Conținutului',
  'terms.content.body': 'Menții dreptul de proprietate asupra întregului conținut pe care îl creezi și îl trimiți prin serviciu. Nu revendicăm proprietatea asupra email-urilor tale sau a atașamentelor. Putem procesa conținutul după cum este necesar pentru a oferi serviciul.',
  'terms.limitation.title': 'Limitarea Responsabilității',
  'terms.limitation.body': 'Chatyy este furnizat "ca atare". Ne străduim pentru o disponibilitate de 99,9%, dar nu garantăm un serviciu neîntrerupt. Nu suntem responsabili pentru daune indirecte, incidentale sau consecvente rezultate din utilizarea serviciului.',
  'terms.termination.title': 'Încetarea Contului',
  'terms.termination.body': 'Putem suspenda sau închide conturile care încalcă acești termeni. Poți șterge contul tău în orice moment în Setări. După închidere, datele tale vor fi șterse în maxim 30 de zile.',
  'terms.changes.title': 'Modificări ale Termenilor',
  'terms.changes.body': 'Putem actualiza acești termeni periodic. Te vom notifica despre modificările semnificative prin email sau notificare în aplicație. Utilizarea continuată după modificări constituie acceptarea termenilor actualizați.',
